"""
recipes.py

A recipe scaler and shopping-list generator with features:
- Unit conversion support for common cooking units (volume, weight, count)
- Ingredient merging to combine amounts of the same ingredient with compatible units
- Recipe scaling by servings
- Pantry subtraction to avoid buying ingredients already available
"""

from typing import Dict, List, Tuple, Optional, Union
import copy

# Define supported units and conversion factors to a base unit for volume and weight
VOLUME_UNITS_TO_ML = {
    'ml': 1.0,
    'l': 1000.0,
    'tsp': 4.92892,
    'tbsp': 14.7868,
    'fl oz': 29.5735,
    'cup': 240.0,
    'pint': 473.176,
    'quart': 946.353,
    'gallon': 3785.41
}

WEIGHT_UNITS_TO_G = {
    'g': 1.0,
    'kg': 1000.0,
    'oz': 28.3495,
    'lb': 453.592
}

# Units considered as count units or no conversion
COUNT_UNITS = ['unit', 'count', 'item', 'pcs', 'piece', 'clove', 'slice']

# Type alias for ingredient quantities
QuantityType = Union[float, Tuple[float, str]]  # either a number or (number, unit)

class Ingredient:
    """
    Represents a single ingredient with a name, quantity, and unit.
    """
    def __init__(self, name: str, amount: float, unit: str):
        self.name = name.lower().strip()
        self.amount = amount
        self.unit = unit.lower().strip()

    def __repr__(self):
        return f"Ingredient(name='{self.name}', amount={self.amount}, unit='{self.unit}')"

    def to_ml(self) -> Optional[float]:
        # Convert this ingredient amount to ml if a volume unit
        if self.unit in VOLUME_UNITS_TO_ML:
            return self.amount * VOLUME_UNITS_TO_ML[self.unit]
        return None

    def to_g(self) -> Optional[float]:
        # Convert this ingredient amount to grams if a weight unit
        if self.unit in WEIGHT_UNITS_TO_G:
            return self.amount * WEIGHT_UNITS_TO_G[self.unit]
        return None

    def is_volume_unit(self) -> bool:
        return self.unit in VOLUME_UNITS_TO_ML

    def is_weight_unit(self) -> bool:
        return self.unit in WEIGHT_UNITS_TO_G

    def is_count_unit(self) -> bool:
        return self.unit in COUNT_UNITS

    def compatible_with(self, other: 'Ingredient') -> bool:
        # Two ingredients are compatible for merging if names match and units are compatible
        if self.name != other.name:
            return False
        if self.unit == other.unit:
            return True
        if (self.is_volume_unit() and other.is_volume_unit()) or (self.is_weight_unit() and other.is_weight_unit()):
            return True
        if self.is_count_unit() and other.is_count_unit():
            return True
        return False

    def merge(self, other: 'Ingredient') -> 'Ingredient':
        # Merge another compatible ingredient into this one, converting units as needed
        if not self.compatible_with(other):
            raise ValueError(f"Incompatible ingredients for merge: {self} vs {other}")
        # Prefer weight units if any are weight
        if self.is_weight_unit() and other.is_weight_unit():
            base_amount = self.to_g() + other.to_g()
            return Ingredient(self.name, base_amount, 'g')
        # Prefer volume units if any are volume
        if self.is_volume_unit() and other.is_volume_unit():
            base_amount = self.to_ml() + other.to_ml()
            return Ingredient(self.name, base_amount, 'ml')
        # Count units just add
        if self.is_count_unit() and other.is_count_unit():
            return Ingredient(self.name, self.amount + other.amount, self.unit)
        # If mismatched or unknown units, fallback to raising error
        raise ValueError(f"Cannot merge ingredients with incompatible units: {self} vs {other}")

    def scale(self, factor: float) -> 'Ingredient':
        # Return a new ingredient scaled by factor
        return Ingredient(self.name, self.amount * factor, self.unit)

    def subtract(self, other: 'Ingredient') -> Optional['Ingredient']:
        # Subtract quantity of other ingredient from this one, if compatible
        if not self.compatible_with(other):
            return copy.deepcopy(self)
        # Convert both to base unit
        if self.is_weight_unit() and other.is_weight_unit():
            diff = self.to_g() - other.to_g()
            if diff <= 0:
                return None
            return Ingredient(self.name, diff, 'g')
        if self.is_volume_unit() and other.is_volume_unit():
            diff = self.to_ml() - other.to_ml()
            if diff <= 0:
                return None
            return Ingredient(self.name, diff, 'ml')
        if self.is_count_unit() and other.is_count_unit():
            diff = self.amount - other.amount
            if diff <= 0:
                return None
            return Ingredient(self.name, diff, self.unit)
        return copy.deepcopy(self)


def merge_ingredients(ingredients: List[Ingredient]) -> List[Ingredient]:
    """
    Merge ingredients with the same name and compatible units by summing their amounts.

    Args:
        ingredients (List[Ingredient]): List of ingredients to merge.

    Returns:
        List[Ingredient]: Merged list of ingredients.
    """
    merged = []
    for ing in ingredients:
        found = False
        for i, m in enumerate(merged):
            if m.compatible_with(ing):
                merged[i] = m.merge(ing)
                found = True
                break
        if not found:
            merged.append(copy.deepcopy(ing))
    return merged

class Recipe:
    """
    Represents a recipe with a name, servings, and a list of ingredients.
    """
    def __init__(self, name: str, servings: int, ingredients: List[Ingredient]):
        self.name = name
        self.servings = servings
        self.ingredients = merge_ingredients(ingredients)

    def scale(self, new_servings: int) -> 'Recipe':
        """
        Return a new recipe scaled to a different number of servings.
        """
        factor = new_servings / self.servings
        scaled_ingredients = [ing.scale(factor) for ing in self.ingredients]
        return Recipe(self.name, new_servings, scaled_ingredients)

    def subtract_pantry(self, pantry: Dict[str, Ingredient]) -> 'Recipe':
        """
        Subtract quantities available in pantry from ingredients.

        Args:
            pantry (Dict[str, Ingredient]): Dictionary of pantry ingredients keyed by name.

        Returns:
            Recipe: New recipe with pantry subtracted amounts.
        """
        result_ingredients = []
        for ing in self.ingredients:
            pantry_ing = pantry.get(ing.name)
            if pantry_ing:
                subtracted = ing.subtract(pantry_ing)
                if subtracted:
                    result_ingredients.append(subtracted)
            else:
                result_ingredients.append(copy.deepcopy(ing))
        return Recipe(self.name, self.servings, result_ingredients)

    def get_shopping_list(self) -> List[Ingredient]:
        """
        Return the shopping list of ingredients needed (after pantry subtraction).
        """
        return merge_ingredients(self.ingredients)

    def __repr__(self):
        ings = ', '.join([f'{ing.amount:.2f} {ing.unit} {ing.name}' for ing in self.ingredients])
        return f"Recipe(name='{self.name}', servings={self.servings}, ingredients=[{ings}])"

# Sample pantry class for convenience
class Pantry:
    def __init__(self, items: List[Ingredient]):
        self.items = {item.name: item for item in items}

    def add_item(self, ingredient: Ingredient):
        if ingredient.name in self.items:
            self.items[ingredient.name] = self.items[ingredient.name].merge(ingredient)
        else:
            self.items[ingredient.name] = copy.deepcopy(ingredient)

    def remove_item(self, ingredient: Ingredient):
        if ingredient.name in self.items:
            subtracted = self.items[ingredient.name].subtract(ingredient)
            if subtracted:
                self.items[ingredient.name] = subtracted
            else:
                del self.items[ingredient.name]

    def to_dict(self) -> Dict[str, Ingredient]:
        return self.items


# Example demo function

def demo():
    # Define a recipe
    recipe = Recipe(
        "Pancakes",
        servings=4,
        ingredients=[
            Ingredient("Flour", 2, "cup"),
            Ingredient("Milk", 1.5, "cup"),
            Ingredient("Egg", 2, "unit"),
            Ingredient("Sugar", 2, "tbsp"),
            Ingredient("Salt", 0.5, "tsp"),
            Ingredient("Butter", 2, "tbsp")
        ]
    )

    print(f"Original recipe: {recipe}")

    # Scale recipe to 2 servings
    scaled = recipe.scale(2)
    print(f"Scaled recipe (2 servings): {scaled}")

    # Define pantry items
    pantry_items = [
        Ingredient("flour", 1, "cup"),
        Ingredient("milk", 0.5, "cup"),
        Ingredient("egg", 1, "unit"),
        Ingredient("salt", 0.25, "tsp")
    ]
    pantry = Pantry(pantry_items)

    # Subtract pantry and get shopping list
    shopping_needed = scaled.subtract_pantry(pantry.to_dict())
    print(f"Shopping list after pantry subtraction: {shopping_needed}")

    for ing in shopping_needed.get_shopping_list():
        print(f"- {ing.amount:.2f} {ing.unit} {ing.name}")


if __name__ == '__main__':
    demo()
